vertex:
#version 300 es

struct VS_OUT
{
    vec2 vTexCoords;
    float vGrey;
    float vAlpha;
};

layout(std140) uniform ObjectUniformBuffer
{
    mat4 g_mModel;
    mat4 g_mView;
    mat4 g_mProj;
    vec3 g_vLightPos;
    vec3 g_vLightColor;
    vec3 g_vCameraPos;
    float g_flTime;
} g_oUbo;

out vec2 vdspv_fsin0_vTexCoords;
out float vdspv_fsin0_vGrey;
out float vdspv_fsin0_vAlpha;
layout(location = 2) in vec2 texCoords;
layout(location = 1) in vec3 tint;
layout(location = 0) in vec3 position;

void main()
{
    vdspv_fsin0_vTexCoords = texCoords;
    vdspv_fsin0_vGrey = tint.x;
    vdspv_fsin0_vAlpha = tint.y;
    gl_Position = vec4(position, tint.z);
    gl_Position.z = 2.0 * gl_Position.z - gl_Position.w;
    gl_Position.y = -gl_Position.y;
}

fragment:
#version 300 es
precision mediump float;
precision highp int;

struct VS_OUT
{
    highp vec2 vTexCoords;
    highp float vGrey;
    highp float vAlpha;
};

uniform highp sampler2D Color;

in highp vec2 vdspv_fsin0_vTexCoords;
in highp float vdspv_fsin0_vGrey;
in highp float vdspv_fsin0_vAlpha;
layout(location = 0) out highp vec4 fragColor;

void main()
{
    highp vec4 vColor = texture(Color, vdspv_fsin0_vTexCoords);
    highp float alpha = vColor.w * vdspv_fsin0_vAlpha;
    if (alpha < 0.062745101749897003173828125)
    {
        discard;
    }
    fragColor = vec4(vColor.xyz * vdspv_fsin0_vGrey, alpha);
}
